const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aleppo = ee.Geometry.Point([37.1611, 36.2021]);
  const aoi = aleppo.buffer(5000); // 5km buffer around the city center
  const startDate2012 = '2012-01-01';
  const endDate2012 = '2012-12-31';
  const startDate2016 = '2016-01-01';
  const endDate2016 = '2016-12-31';
  const scale = 1000; // Use a larger scale to avoid timeout

  // 2. Data Acquisition & Check
  const collectionId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
  const band = 'avg_rad';

  const col2012 = ee.ImageCollection(collectionId)
    .filterBounds(aoi)
    .filterDate(startDate2012, endDate2012)
    .select(band);

  const col2016 = ee.ImageCollection(collectionId)
    .filterBounds(aoi)
    .filterDate(startDate2016, endDate2016)
    .select(band);

  const size2012 = col2012.size().getInfo();
  const size2016 = col2016.size().getInfo();

  if (size2012 === 0 || size2016 === 0) {
    console.log(`Image count 2012: ${size2012}`);
    console.log(`Image count 2016: ${size2016}`);
    console.log('C1: Empty Collection. No images found for one or both years.');
    console.log('A');
    return;
  }
  console.log(`Image count 2012: ${size2012}`);
  console.log(`Image count 2016: ${size2016}`);

  // 3. Processing
  const meanImage2012 = col2012.mean();
  const meanImage2016 = col2016.mean();

  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2012 = meanImage2012.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const stats2016 = meanImage2016.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  // 4. Calculation & Validation
  const val2012 = stats2012['avg_rad_mean'];
  const count2012 = stats2012['avg_rad_count'];

  const val2016 = stats2016['avg_rad_mean'];
  const count2016 = stats2016['avg_rad_count'];

  if (count2012 === 0 || count2016 === 0) {
    console.log(`Valid pixels 2012: ${count2012}`);
    console.log(`Valid pixels 2016: ${count2016}`);
    console.log('C2: No Valid Pixels found after processing.');
    console.log('A');
    return;
  }
  console.log(`Aleppo 2012 Avg Radiance: ${val2012.toFixed(2)} (Pixels: ${count2012})`);
  console.log(`Aleppo 2016 Avg Radiance: ${val2016.toFixed(2)} (Pixels: ${count2016})`);

  if (val2012 === null || val2016 === null || isNaN(val2012) || isNaN(val2016)) {
    console.log('C3: Calculation Failure. Result is null or NaN.');
    console.log('A');
    return;
  }

  // 5. Final Answer
  if (val2016 < val2012) {
    console.log('Conclusion: Nighttime light intensity decreased from 2012 to 2016.');
    console.log('A');
  } else {
    console.log('Conclusion: Nighttime light intensity did not decrease from 2012 to 2016.');
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
